-- Fixes two problems in the Prestige bed-linen line (sheets, fitted sheets,
-- pillowcases, towels), both introduced by the 2026-10-10/11 CSV import:
--
-- 1. DUPLICATES. 16 InnStyle rows (SKUs shaped like
--    "INN-BED-FLS-FL-81X102-T200-CS24") already carry a correct
--    product_family/variant_label from an earlier pass, but are exact
--    physical duplicates of 16 rows in the newer import (same dimensions,
--    same thread-count tier, same pocket depth where applicable -- matched
--    live before writing this, not assumed). Same root cause as the
--    152-product InnStyle duplicate batch fixed in
--    20261010b_deactivate_duplicate_innstyle_batch.sql: the newer rows
--    carry richer data (T300/T600 tiers and "1 Piece" single-unit options
--    this older batch never had), so the older 16 are deactivated and the
--    newer rows are kept, same precedent as that earlier fix.
--
-- 2. NO GROUPING. The remaining 140 Prestige rows from that same import
--    landed with product_family/variant_label/family_key all NULL --
--    every size/pack combination rendered as its own separate storefront
--    card instead of one card with a dropdown. Root cause: admin.js's
--    CSV Converter only auto-derived these from a DASH-separated name
--    ("Family - size, spec"); this vendor feed uses a comma-first format
--    ("Family, size, spec") that fell through ungrouped. Fixed in admin.js
--    (cvtDeriveVariantComma + cvtGroupVariants, this same commit) so future
--    imports of this format group automatically; this migration backfills
--    the 128 of 140 rows that fix can safely group (the other 12 are
--    genuinely solo items -- one bath-mat size, one hand-towel size, etc,
--    with no sibling in this file to put in a dropdown with).
--
-- Values below were generated by running the exact same grouping function
-- now in admin.js against this file's real product names (not hand-typed),
-- then verified for zero variant_label collisions within any family before
-- this file was written.

-- Part 1: deactivate the 16 older, now-duplicate InnStyle rows.
update public.products
set is_active = false, updated_at = now()
where sku in (
  'INN-BED-FTS-CKG-72X84-P12-T200-CS12',
  'INN-BED-FLS-FL-81X102-T200-CS24',
  'INN-BED-FLS-FL-81X104-T200-CS24',
  'INN-BED-FLS-FL-81X109-T200-CS24',
  'INN-BED-FLS-FL-81X98-T200-CS24',
  'INN-BED-FTS-FXL-54X80-P12-T200-CS24',
  'INN-BED-FTS-HKG-72X80-P12-T200-CS12',
  'INN-BED-FTS-KG-78X80-P12-T200-CS12',
  'INN-BED-FTS-KG-78X80-P15-T200-CS12',
  'INN-BED-FLS-KG-108X104-T200-CS12',
  'INN-BED-FLS-KG-108X109-T200-CS12',
  'INN-BED-PCS-KG-20X40-T200-CS72',
  'INN-BED-FLS-KXL-108X114-T200-CS12',
  'INN-BED-FLS-QEW-96X109-T200-CS12',
  'INN-BED-FTS-TXL-39X80-P12-T200-CS24',
  'INN-BED-FTS-FL-54X75-P12-T600-LXB-CS24'
);

-- Part 2: group the 128 newer rows into their size/pack dropdown families.
update public.products set product_family = 'Prestige Ringspun Cotton Bath Mat', variant_label = 'Case of 60 - 20 × 30 in.', family_key = 'prestige-ringspun-cotton-bath-mat', updated_at = now() where sku = 'BM2030RC60';
