-- Safety-net checks: run these after the updates above and confirm both
-- numbers before trusting the result.
--   1) expect 16 -- the duplicate old rows just deactivated.
select count(*) as deactivated_count
from public.products
where sku in (
  'INN-BED-FTS-CKG-72X84-P12-T200-CS12','INN-BED-FLS-FL-81X102-T200-CS24',
  'INN-BED-FLS-FL-81X104-T200-CS24','INN-BED-FLS-FL-81X109-T200-CS24',
  'INN-BED-FLS-FL-81X98-T200-CS24','INN-BED-FTS-FXL-54X80-P12-T200-CS24',
  'INN-BED-FTS-HKG-72X80-P12-T200-CS12','INN-BED-FTS-KG-78X80-P12-T200-CS12',
  'INN-BED-FTS-KG-78X80-P15-T200-CS12','INN-BED-FLS-KG-108X104-T200-CS12',
  'INN-BED-FLS-KG-108X109-T200-CS12','INN-BED-PCS-KG-20X40-T200-CS72',
  'INN-BED-FLS-KXL-108X114-T200-CS12','INN-BED-FLS-QEW-96X109-T200-CS12',
  'INN-BED-FTS-TXL-39X80-P12-T200-CS24','INN-BED-FTS-FL-54X75-P12-T600-LXB-CS24'
) and is_active = false;

--   2) expect 0 -- no Prestige product should still be ungrouped after this
--      migration except the 12 genuinely-solo items (Luxury Turkish single
--      sizes, Ringspun Cotton Double-Dobby/Hand Towel/Washcloth, Suites).
select count(*) as still_ungrouped_unexpected
from public.products
where name ilike 'Prestige%'
  and product_family is null
  and is_active = true
  and sku not in (
    'BM2234LC20','BS3060LC12','BT2758LC14','HT1630LC42','WC1313LC110',
    'BT3060RDC24','HT1630RC120','WC1313RC300',
    'BM2035SC12','BT3056SC12','HT1628SC24','WC1313SC48'
  );

--   3) expect 0 rows -- confirms no family created above has two members
--      sharing the same variant_label (would make the dropdown ambiguous).
select product_family, variant_label, count(*)
from public.products
where name ilike 'Prestige%' and is_active = true and product_family is not null
group by product_family, variant_label
having count(*) > 1;
